  const hc = settings.hiringCafe || {};
  const every = Math.max(15, hc.everyMinutes || 60);
  const minuteOfDay = Math.floor(((now || Date.now()) / 60000) % 1440);
  if (hc.enabled && minuteOfDay % every < 15) {
