    for (const j of data.content) {
      const loc = j.location || {};
      out.push(mk({ uid: `smartrecruiters:${req.slug}:${j.id}`, source: s, sourceLabel: 'SmartRecruiters (direct)', company: req.company || (j.company && j.company.name), dream: req.dream,
